     1	// A local graphical consumer for the successor queue modules, not an asset generator. Copied from renderer/server.mjs; rendererRoot resolves to this folder.
     2	import { createServer } from 'node:http';
     3	import { readFile, realpath } from 'node:fs/promises';
     4	import { resolve, relative, sep, dirname, extname } from 'node:path';
     5	import { fileURLToPath } from 'node:url';
     6	import { stripTypeScriptTypes } from 'node:module';
     7	import { createHash } from 'node:crypto';
     8	
     9	export const rendererRoot = dirname(fileURLToPath(import.meta.url));
    10	export const hash = bytes => createHash('sha256').update(bytes).digest('hex');
    11	
    12	export async function serve(project, onCapture = null) {
    13	  const root = await realpath(project);
    14	  const served = new Map();
    15	  const server = createServer(async (request, response) => {
    16	    try {
    17	      const url = new URL(request.url, 'http://127.0.0.1');
    18	      if (url.pathname === '/__capture' && request.method === 'POST' && onCapture) {
    19	        let body = '';
    20	        for await (const chunk of request) {
    21	          body += chunk;
    22	          if (body.length > 4_000_000) throw new Error('Capture exceeds local limit');
    23	        }
    24	        await onCapture(JSON.parse(body));
    25	        response.writeHead(200, { 'Content-Type': 'text/plain' }).end('retained');
    26	        return;
    27	      }
    28	      if (request.method !== 'GET') {
    29	        response.writeHead(405).end();
    30	        return;
    31	      }
    32	      const pathname = decodeURIComponent(url.pathname);
    33	      const own = pathname === '/' || pathname === '/view.mjs';
    34	      if (!own && !pathname.startsWith('/src/') && !pathname.startsWith('/assets/')) {
    35	        response.writeHead(404).end('Not a consumer resource');
    36	        return;
    37	      }
    38	      const base = own ? rendererRoot : root;
    39	      const name = pathname === '/' ? 'index.html' : pathname.slice(1);
    40	      const path = await realpath(resolve(base, name));
    41	      const rel = relative(base, path);
    42	      if (rel === '..' || rel.startsWith(`..${sep}`) || resolve(base, rel) !== path) {
    43	        response.writeHead(403).end('Outside consumer');
    44	        return;
    45	      }
    46	      const bytes = await readFile(path);
    47	      served.set(`${own ? 'renderer' : 'consumer'}/${rel.replaceAll(sep, '/')}`, hash(bytes));
    48	      const extension = extname(path);
    49	      const type = { '.html': 'text/html', '.mjs': 'text/javascript', '.ts': 'text/javascript', '.png': 'image/png', '.svg': 'image/svg+xml' }[extension];
    50	      if (!type) { response.writeHead(415).end(); return; }
    51	      response.writeHead(200, { 'Content-Type': type, 'Cache-Control': 'no-store' });
    52	      response.end(extension === '.ts' ? stripTypeScriptTypes(bytes.toString('utf8')) : bytes);
    53	    } catch (error) {
    54	      const missing = error.code === 'ENOENT';
    55	      response.writeHead(missing ? 404 : 500).end(missing ? 'Missing consumer asset' : String(error));
    56	    }
    57	  });
    58	  await new Promise((yes, no) => { server.once('error', no); server.listen(0, '127.0.0.1', yes); });
    59	  return { server, root, served, url: `http://127.0.0.1:${server.address().port}` };
    60	}
    61	
    62	if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
    63	  const flag = process.argv.indexOf('--project');
    64	  const project = flag < 0 ? resolve(rendererRoot, '..') : resolve(process.argv[flag + 1]);
    65	  const running = await serve(project);
    66	  console.log(JSON.stringify({ url: running.url, project: running.root, node: process.version }));
    67	}

