# Independent caller measurement of the actual art (not copied from the specialist)
import hashlib,json
from PIL import Image
def sha(p): return hashlib.sha256(open(p,'rb').read()).hexdigest()
def comps(img):
    w,h=img.size; px=img.load(); seen=set(); out=[]
    for y in range(h):
        for x in range(w):
            if px[x,y][3]>0 and (x,y) not in seen:
                st=[(x,y)]; seen.add((x,y)); pts=[]
                while st:
                    cx,cy=st.pop(); pts.append((cx,cy))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=cx+dx,cy+dy
                        if 0<=nx<w and 0<=ny<h and (nx,ny) not in seen and px[nx,ny][3]>0:
                            seen.add((nx,ny)); st.append((nx,ny))
                xs=[p[0] for p in pts]; ys=[p[1] for p in pts]
                out.append({'pixels':len(pts),'box':[min(xs),min(ys),max(xs)+1,max(ys)+1]})
    return out
def hist(img):
    h={}
    for p in img.getdata(): h[p[3]]=h.get(p[3],0)+1
    return h
res={}
sheet=Image.open('assets/working.png').convert('RGBA')
res['working']={'sha256':sha('assets/working.png'),'size':sheet.size}
cells=[sheet.crop((i*16,0,(i+1)*16,16)) for i in range(4)]
def vis(img): return [(x,y,img.getpixel((x,y))) for y in range(16) for x in range(16) if img.getpixel((x,y))[3]>0]
def cw(img):
    out=Image.new('RGBA',(16,16),(0,0,0,0))
    for y in range(16):
        for x in range(16):
            out.putpixel((x,y),img.getpixel((y,15-x)))
    return out
c0=cells[0]
eq=[]
rot=c0
for k in range(1,4):
    rot=cw(rot)
    eq.append(vis(rot)==vis(cells[k]) and [p[3] for p in rot.getdata()]==[p[3] for p in cells[k].getdata()])
res['cells_equal_cw_k_cell0']=eq
res['cell0']={'hist':hist(c0),'components':comps(c0)}
seedp='.pixl/assets/queue.ready/artifacts/21f5baca68958eaa30d89fe9ec216e2b8dfc9e4a941f80b8a19fa0e712939629.png'
import os
if not os.path.exists(seedp):
    import glob; g=glob.glob('.pixl/assets/queue.ready/artifacts/21f5baca*'); seedp=g[0] if g else None
if seedp:
    seed=Image.open(seedp).convert('RGBA'); res['seed']={'path':seedp,'sha256':sha(seedp),'size':seed.size,'cell0_equals_seed_visible':vis(seed)==vis(c0)}
for name in ['ready-confirmed','paused','error-retry']:
    im=Image.open(f'assets/{name}.png').convert('RGBA')
    res[name]={'sha256':sha(f'assets/{name}.png'),'size':im.size,'hist':hist(im),'components':comps(im)}
# colors
cols={}
for p in sheet.getdata():
    if p[3]>0: cols[p]=cols.get(p,0)+1
res['working_visible_colors']=sorted(((v,k) for k,v in cols.items()),reverse=True)
print(json.dumps(res,indent=1,default=str))
